//! Runtime for mechanically lifted functions (generated by scripts/lift.py into p2v/*.rs).
//!
//! The lifted code keeps the 16 general registers, the xmm registers and the flags in Rust locals, the stack
//! frame in a 128 KB window at the oracle's stack addresses, and sends every other memory access and every call
//! through `neutral_world::Env`. Flag semantics follow x86 (and QEMU for undefined flags). Nothing here is
//! specific to one function.

use neutral_world::{CallRet, Env, STK};

/// Size of the dump (rel_to_end 0 is the first byte after it).
pub const CODE_N: u64 = 964659;
/// rsp the oracle starts the function with, plus 8 (the return address sits at RSP0 - 8).
pub const RSP0: u64 = 0x7fff_f000;
/// Stack window held by [`Mem`]: [WIN_LO, WIN_LO + WIN).
const WIN_LO: u64 = 0x7ffe_0000;
const WIN: usize = 0x2_0000;
/// Addresses the world harness normalises to `STK` in call arguments.
const NORM_LO: u64 = 0x7ff0_0000;
const NORM_HI: u64 = 0x8000_1000;

pub const SAVED_RBX: u64 = 0x1111_1111_1111_1111;
pub const SAVED_RBP: u64 = 0x2222_2222_2222_2222;
pub const SAVED_R12: u64 = 0x3333_3333_3333_3333;
pub const SAVED_R13: u64 = 0x4444_4444_4444_4444;
pub const SAVED_R14: u64 = 0x5555_5555_5555_5555;
pub const SAVED_R15: u64 = 0x6666_6666_6666_6666;

/// Registers a lifted function returns (the spec decides which ones are compared).
#[derive(Debug, Clone, Copy, Default)]
pub struct Ret {
    pub rax: u64,
    pub rdx: u64,
    pub xmm0: u128,
}

impl Ret {
    pub fn from_call(r: CallRet) -> Ret {
        Ret { rax: r.rax, rdx: r.rdx, xmm0: (r.xmm0_lo as u128) | ((r.xmm0_hi as u128) << 64) }
    }
}

/// Memory and calls of one lifted run: the stack window plus the world.
pub struct Mem<'a, E: Env> {
    pub env: &'a mut E,
    stk: Vec<u8>,
}

#[inline(always)]
fn norm(v: u64) -> u64 {
    if (NORM_LO..NORM_HI).contains(&v) {
        STK
    } else {
        v
    }
}

macro_rules! rd_impl {
    ($name:ident, $envname:ident, $t:ty, $n:expr) => {
        #[inline(always)]
        pub fn $name(&mut self, a: u64) -> $t {
            if a >= WIN_LO && a + $n <= WIN_LO + WIN as u64 {
                let o = (a - WIN_LO) as usize;
                <$t>::from_le_bytes(self.stk[o..o + $n].try_into().unwrap())
            } else {
                self.env.$envname(a)
            }
        }
    };
}

macro_rules! wr_impl {
    ($name:ident, $envname:ident, $t:ty, $n:expr) => {
        #[inline(always)]
        pub fn $name(&mut self, a: u64, v: $t) {
            if a >= WIN_LO && a + $n <= WIN_LO + WIN as u64 {
                let o = (a - WIN_LO) as usize;
                self.stk[o..o + $n].copy_from_slice(&v.to_le_bytes());
            } else {
                self.env.$envname(a, v)
            }
        }
    };
}

impl<'a, E: Env> Mem<'a, E> {
    /// `st` are the stack arguments (slot k at RSP0 + 8k).
    pub fn new(env: &'a mut E, st: &[u64]) -> Self {
        let mut m = Mem { env, stk: vec![0u8; WIN] };
        for (k, v) in st.iter().enumerate() {
            m.w64(RSP0 + 8 * k as u64, *v);
        }
        m.w64(RSP0 - 8, 0x0dea_d000);
        m
    }
    rd_impl!(r8, r8, u8, 1);
    rd_impl!(r16, r16, u16, 2);
    rd_impl!(r32, r32, u32, 4);
    rd_impl!(r64, r64, u64, 8);
    rd_impl!(r128, r128, u128, 16);
    wr_impl!(w8, w8, u8, 1);
    wr_impl!(w16, w16, u16, 2);
    wr_impl!(w32, w32, u32, 4);
    wr_impl!(w64, w64, u64, 8);
    wr_impl!(w128, w128, u128, 16);

    /// Call through the world; stack addresses in the arguments become `STK` like in the oracle's trace.
    pub fn call(&mut self, target: u64, iargs: &[u64], fargs: &[u64]) -> CallRet {
        let ia: Vec<u64> = iargs.iter().map(|v| norm(*v)).collect();
        self.env.call_f(target, &ia, fargs)
    }
}

/// Arithmetic flags (af is not modelled; nothing in the dump depends on it).
#[derive(Debug, Clone, Copy, Default)]
pub struct Fl {
    pub cf: bool,
    pub zf: bool,
    pub sf: bool,
    pub of: bool,
    pub pf: bool,
}

impl Fl {
    #[inline(always)]
    pub fn e(&self) -> bool { self.zf }
    #[inline(always)]
    pub fn ne(&self) -> bool { !self.zf }
    #[inline(always)]
    pub fn b(&self) -> bool { self.cf }
    #[inline(always)]
    pub fn ae(&self) -> bool { !self.cf }
    #[inline(always)]
    pub fn be(&self) -> bool { self.cf || self.zf }
    #[inline(always)]
    pub fn a(&self) -> bool { !self.cf && !self.zf }
    #[inline(always)]
    pub fn l(&self) -> bool { self.sf != self.of }
    #[inline(always)]
    pub fn ge(&self) -> bool { self.sf == self.of }
    #[inline(always)]
    pub fn le(&self) -> bool { self.zf || self.sf != self.of }
    #[inline(always)]
    pub fn g(&self) -> bool { !self.zf && self.sf == self.of }
    #[inline(always)]
    pub fn s(&self) -> bool { self.sf }
    #[inline(always)]
    pub fn ns(&self) -> bool { !self.sf }
    #[inline(always)]
    pub fn o(&self) -> bool { self.of }
    #[inline(always)]
    pub fn no(&self) -> bool { !self.of }
    #[inline(always)]
    pub fn p(&self) -> bool { self.pf }
    #[inline(always)]
    pub fn np(&self) -> bool { !self.pf }
}

#[inline(always)]
pub fn mask<const W: u32>() -> u64 {
    if W == 64 {
        u64::MAX
    } else {
        (1u64 << W) - 1
    }
}

#[inline(always)]
fn sign<const W: u32>(v: u64) -> bool {
    (v >> (W - 1)) & 1 != 0
}

#[inline(always)]
fn par(r: u64) -> bool {
    (r as u8).count_ones() % 2 == 0
}

#[inline(always)]
fn zsp<const W: u32>(r: u64) -> (bool, bool, bool) {
    (r == 0, sign::<W>(r), par(r))
}

/// Sign-extends the W-bit value to i64.
#[inline(always)]
pub fn sx<const W: u32>(v: u64) -> i64 {
    let sh = 64 - W;
    ((v << sh) as i64) >> sh
}

pub fn add<const W: u32>(a: u64, b: u64) -> (u64, Fl) {
    let m = mask::<W>();
    let (a, b) = (a & m, b & m);
    let r = a.wrapping_add(b) & m;
    let (zf, sf, pf) = zsp::<W>(r);
    (r, Fl { cf: r < a, zf, sf, of: sign::<W>((a ^ r) & (b ^ r)), pf })
}

pub fn adc<const W: u32>(a: u64, b: u64, c: bool) -> (u64, Fl) {
    let m = mask::<W>();
    let (a, b) = (a & m, b & m);
    let r = a.wrapping_add(b).wrapping_add(c as u64) & m;
    let (zf, sf, pf) = zsp::<W>(r);
    let cf = (a as u128 + b as u128 + c as u128) > m as u128;
    (r, Fl { cf, zf, sf, of: sign::<W>((a ^ r) & (b ^ r)), pf })
}

pub fn sub<const W: u32>(a: u64, b: u64) -> (u64, Fl) {
    let m = mask::<W>();
    let (a, b) = (a & m, b & m);
    let r = a.wrapping_sub(b) & m;
    let (zf, sf, pf) = zsp::<W>(r);
    (r, Fl { cf: a < b, zf, sf, of: sign::<W>((a ^ b) & (a ^ r)), pf })
}

pub fn sbb<const W: u32>(a: u64, b: u64, c: bool) -> (u64, Fl) {
    let m = mask::<W>();
    let (a, b) = (a & m, b & m);
    let r = a.wrapping_sub(b).wrapping_sub(c as u64) & m;
    let (zf, sf, pf) = zsp::<W>(r);
    let cf = (a as u128) < (b as u128 + c as u128);
    (r, Fl { cf, zf, sf, of: sign::<W>((a ^ b) & (a ^ r)), pf })
}

/// Flags of a logic result (and, or, xor, test).
pub fn logic<const W: u32>(r: u64) -> Fl {
    let r = r & mask::<W>();
    let (zf, sf, pf) = zsp::<W>(r);
    Fl { cf: false, zf, sf, of: false, pf }
}

pub fn inc<const W: u32>(a: u64, f: Fl) -> (u64, Fl) {
    let (r, mut n) = add::<W>(a, 1);
    n.cf = f.cf;
    (r, n)
}

pub fn dec<const W: u32>(a: u64, f: Fl) -> (u64, Fl) {
    let (r, mut n) = sub::<W>(a, 1);
    n.cf = f.cf;
    (r, n)
}

pub fn neg<const W: u32>(a: u64) -> (u64, Fl) {
    let (r, mut n) = sub::<W>(0, a);
    n.cf = a & mask::<W>() != 0;
    (r, n)
}

#[inline(always)]
fn cnt_mask<const W: u32>(c: u64) -> u32 {
    (c & if W == 64 { 63 } else { 31 }) as u32
}

pub fn shl<const W: u32>(a: u64, c: u64, f: Fl) -> (u64, Fl) {
    let n = cnt_mask::<W>(c);
    if n == 0 {
        return (a & mask::<W>(), f);
    }
    let m = mask::<W>();
    let a = a & m;
    let r = if n >= 64 { 0 } else { (a << n) & m };
    let cf = if n <= W { (a >> (W - n)) & 1 != 0 } else { false };
    let (zf, sf, pf) = zsp::<W>(r);
    (r, Fl { cf, zf, sf, of: sign::<W>(r) != cf, pf })
}

pub fn shr<const W: u32>(a: u64, c: u64, f: Fl) -> (u64, Fl) {
    let n = cnt_mask::<W>(c);
    if n == 0 {
        return (a & mask::<W>(), f);
    }
    let m = mask::<W>();
    let a = a & m;
    let r = if n >= 64 { 0 } else { a >> n };
    let cf = if n <= W { (a >> (n - 1)) & 1 != 0 } else { false };
    let (zf, sf, pf) = zsp::<W>(r);
    (r, Fl { cf, zf, sf, of: sign::<W>(a), pf })
}

pub fn sar<const W: u32>(a: u64, c: u64, f: Fl) -> (u64, Fl) {
    let n = cnt_mask::<W>(c);
    if n == 0 {
        return (a & mask::<W>(), f);
    }
    let v = sx::<W>(a);
    let r = ((v >> n.min(63)) as u64) & mask::<W>();
    let cf = ((v >> (n - 1).min(63)) & 1) != 0;
    let (zf, sf, pf) = zsp::<W>(r);
    (r, Fl { cf, zf, sf, of: false, pf })
}

pub fn rol<const W: u32>(a: u64, c: u64, f: Fl) -> (u64, Fl) {
    let n = cnt_mask::<W>(c);
    if n == 0 {
        return (a & mask::<W>(), f);
    }
    let m = mask::<W>();
    let a = a & m;
    let k = n % W;
    let r = if k == 0 { a } else { ((a << k) | (a >> (W - k))) & m };
    let cf = r & 1 != 0;
    (r, Fl { cf, of: sign::<W>(r) != cf, ..f })
}

pub fn ror<const W: u32>(a: u64, c: u64, f: Fl) -> (u64, Fl) {
    let n = cnt_mask::<W>(c);
    if n == 0 {
        return (a & mask::<W>(), f);
    }
    let m = mask::<W>();
    let a = a & m;
    let k = n % W;
    let r = if k == 0 { a } else { ((a >> k) | (a << (W - k))) & m };
    let cf = sign::<W>(r);
    let of = (((r >> (W - 1)) ^ (r >> (W - 2))) & 1) != 0;
    (r, Fl { cf, of, ..f })
}

/// Two/three operand imul: the low W bits of the signed product; cf = of = the product does not fit.
pub fn imul<const W: u32>(a: u64, b: u64) -> (u64, Fl) {
    let p = (sx::<W>(a) as i128) * (sx::<W>(b) as i128);
    let r = (p as u64) & mask::<W>();
    let over = p != sx::<W>(r) as i128;
    let (zf, sf, pf) = zsp::<W>(r);
    (r, Fl { cf: over, zf, sf, of: over, pf })
}

/// One operand mul: returns (low, high, flags) of the unsigned W x W bit product.
pub fn mul1<const W: u32>(a: u64, b: u64) -> (u64, u64, Fl) {
    let m = mask::<W>();
    let p = (a & m) as u128 * (b & m) as u128;
    let lo = (p as u64) & m;
    let hi = ((p >> W) as u64) & m;
    let over = hi != 0;
    let (zf, sf, pf) = zsp::<W>(lo);
    (lo, hi, Fl { cf: over, zf, sf, of: over, pf })
}

/// One operand imul: returns (low, high, flags) of the signed product.
pub fn imul1<const W: u32>(a: u64, b: u64) -> (u64, u64, Fl) {
    let m = mask::<W>();
    let p = (sx::<W>(a) as i128) * (sx::<W>(b) as i128);
    let lo = (p as u64) & m;
    let hi = ((p >> W) as u64) & m;
    let over = p != sx::<W>(lo) as i128;
    let (zf, sf, pf) = zsp::<W>(lo);
    (lo, hi, Fl { cf: over, zf, sf, of: over, pf })
}

/// Unsigned divide of (hi:lo) by d; panics on d == 0 or quotient overflow (the original faults, the case is skipped).
pub fn div<const W: u32>(hi: u64, lo: u64, d: u64) -> (u64, u64) {
    let m = mask::<W>();
    let d = (d & m) as u128;
    assert!(d != 0, "divide by zero");
    let n = (((hi & m) as u128) << W) | (lo & m) as u128;
    let q = n / d;
    assert!(q <= m as u128, "divide overflow");
    (q as u64, (n % d) as u64)
}

pub fn idiv<const W: u32>(hi: u64, lo: u64, d: u64) -> (u64, u64) {
    let m = mask::<W>();
    assert!((d & m) != 0, "divide by zero");
    let n: i128 = ((((hi & m) as u128) << W) | (lo & m) as u128) as i128;
    let n = if W == 64 { n } else { (n << (128 - 2 * W)) >> (128 - 2 * W) };
    let dv = sx::<W>(d) as i128;
    let q = n / dv;
    let r = n % dv;
    let lim = 1i128 << (W - 1);
    assert!(q >= -lim && q < lim, "divide overflow");
    ((q as u64) & m, (r as u64) & m)
}

/// bt/bts/btr/btc with a register or immediate bit offset: returns the selected bit.
#[inline(always)]
pub fn bit<const W: u32>(a: u64, off: u64) -> bool {
    (a >> (off & (W as u64 - 1))) & 1 != 0
}

pub fn bsf<const W: u32>(a: u64) -> Option<u64> {
    let a = a & mask::<W>();
    if a == 0 {
        None
    } else {
        Some(a.trailing_zeros() as u64)
    }
}

pub fn bsr<const W: u32>(a: u64) -> Option<u64> {
    let a = a & mask::<W>();
    if a == 0 {
        None
    } else {
        Some(63 - a.leading_zeros() as u64)
    }
}

// ---- floating point -------------------------------------------------------------------------------------------

#[inline(always)]
pub fn lo64(x: u128) -> u64 {
    x as u64
}

#[inline(always)]
pub fn set_lo64(x: u128, v: u64) -> u128 {
    (x & !(u64::MAX as u128)) | v as u128
}

#[inline(always)]
pub fn set_lo32(x: u128, v: u32) -> u128 {
    (x & !(u32::MAX as u128)) | v as u128
}

#[inline(always)]
pub fn f64_of(x: u128) -> f64 {
    f64::from_bits(x as u64)
}

#[inline(always)]
pub fn f32_of(x: u128) -> f32 {
    f32::from_bits(x as u32)
}

/// comisd/ucomisd/comiss/ucomiss flags.
pub fn ucomi(a: f64, b: f64) -> Fl {
    if a.is_nan() || b.is_nan() {
        Fl { cf: true, zf: true, pf: true, sf: false, of: false }
    } else if a > b {
        Fl::default()
    } else if a < b {
        Fl { cf: true, ..Fl::default() }
    } else {
        Fl { zf: true, ..Fl::default() }
    }
}

/// cvttsd2si / cvttss2si to 32 bits.
pub fn cvtt32(v: f64) -> u32 {
    if v.is_nan() || v >= 2147483648.0 || v <= -2147483649.0 {
        0x8000_0000
    } else {
        (v as i32) as u32
    }
}

pub fn cvtt64(v: f64) -> u64 {
    if v.is_nan() || v >= 9223372036854775808.0 || v < -9223372036854775808.0 {
        0x8000_0000_0000_0000
    } else {
        (v as i64) as u64
    }
}

/// maxsd/minsd style select: `a < b ? a : b` semantics are written out by the generator; helpers for cvtsd2si.
pub fn cvt_round32(v: f64) -> u32 {
    let r = v.round_ties_even();
    if v.is_nan() || r >= 2147483648.0 || r < -2147483648.0 {
        0x8000_0000
    } else {
        (r as i32) as u32
    }
}

pub fn cvt_round64(v: f64) -> u64 {
    let r = v.round_ties_even();
    if v.is_nan() || r >= 9223372036854775808.0 || r < -9223372036854775808.0 {
        0x8000_0000_0000_0000
    } else {
        (r as i64) as u64
    }
}

/// Value the lifted code leaves in registers an opaque call clobbered (the world harness randomises them).
pub const POISON: u64 = 0xdead_beef_dead_beef;
